## Section1(not reported)
## Problem1(3.10.11)
## Author()
## Institution()
## Language(en-US)

DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PGlateximage.pl",
  "contextForm.pl",
  "contextFraction.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

Context("LimitedFraction")->flags->set(requirePureFractions => 1, showMixedNumbers => 0);
@x = random_subset(2, 1 .. 9);
@y = random_subset(2, 1 .. 9);
$m = Fraction($y[1] - $y[0], $x[1] - $x[0]);
Context("Numeric");
Context()->noreduce('(-x)-y', '(-x)+y');
$f = Formula("$m (x - $x[0]) + $y[0]");
Context()->flags->set(reduceConstants => 0);
$top = Formula("x - $y[0]");
$top = $top->substitute(x => $y[1]);
$bottom = Formula("x - $x[0]");
$bottom = $bottom->substitute(x => $x[1]);

$image_1 = createLaTeXImage();
$image_1->addToPreamble(latexImagePreamble());
$image_1->BEGIN_LATEX_IMAGE
\begin{tikzpicture}
  \begin{axis}[
      xmin=-1,
      xmax=10,
      ymin=-1,
      ymax=10,
      xtick={2,4,...,8},
      minor xtick={1,...,9},
      ytick={5,10},
      minor ytick={1,...,9},
      width=0.47\orccaprintwidth
    ]
    \addplot+[domain=-1:10,samples=2] {$f};
  \end{axis}
\end{tikzpicture}

END_LATEX_IMAGE

######
# Body
######

BEGIN_PGML
>> [@image(insertGraph($image_1), width=>282)@]*  <<

[_]{$m}{10}

END_PGML

##########
# Solution
##########

BEGIN_PGML_SOLUTION
First we use the graph to identify two points. We find [`([$x[0]], [$y[0]])`] and [`([$x[1]], [$y[1]])\text{,}`] but you might find another pair of points and the slope will work out to be the same. Using the slope formula:

[```
\begin{aligned}
m \amp= \frac{y_2 - y_1}{x_2 - x_1}\\
\amp= \frac{[$top]}{[$bottom]}\\
\amp= \frac{[$top->reduce]}{[$bottom->reduce]}
\end{aligned}
```]

So the slope is [`[$m]\text{.}`]

END_PGML_SOLUTION

#############
# End Problem
#############

ENDDOCUMENT();
